import{_ as c,a0 as o,w as d,s as p,ao as r,I as t,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT x X-CMD","titleTemplate":false,"description":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 ncurses 在你的 Linux 屏幕上定位文本 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210829 Position text on your screen in Linux with ncurses","title":"使用 ncurses 在你的 Linux 屏幕上定位文本","tag":"202109","desc":""},"relativePath":"202109/20210829 Position text on your screen in Linux with ncurses.md","filePath":"[post].md"}'),l={name:"202109/20210829 Position text on your screen in Linux with ncurses.md"};function u(h,s,g,k,b,m){const n=o("Link");return d(),p("div",null,[s[15]||(s[15]=r(`<h1 id="使用-ncurses-在你的-linux-屏幕上定位文本" tabindex="-1">使用 ncurses 在你的 Linux 屏幕上定位文本 <a class="header-anchor" href="#使用-ncurses-在你的-linux-屏幕上定位文本" aria-label="Permalink to “使用 ncurses 在你的 Linux 屏幕上定位文本”">​</a></h1><blockquote><p>使用 ncurses 在 Linux 屏幕上的特定位置放置文本，可以帶來更友好的用户界面體驗。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202109/06/085908qrdrrv5dru6pcucr.jpg" alt=""></p><p>大多數的 Linux 實用程序僅僅只在屏幕的底部滾動文本。如果你想在屏幕中放置你的文本，例如一個遊戲或者一個數據展示，你可以試試 ncurses。</p><p>curses 是一箇舊的 Unix 庫，它可以在文本終端界面控制光標。curses 的名稱就來自於術語 “<ruby>光標控制<rt>cursor control</rt></ruby>”。多年以後，其他人編寫了新的 curses 版本用來添加新的功能，新版本被叫做 “new curses” 或者 “ncurses”。你可以在每個流行的 Linux 發行版中找到 ncurses。儘管默認情況下可能未安裝開發庫、頭文件和文檔。例如，在 Fedora 上，你需要使用以下命令安裝 <code>ncurses-devel</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ncurses-devel</span></span></code></pre></div><h3 id="在程序中使用-ncurses" tabindex="-1">在程序中使用 ncurses <a class="header-anchor" href="#在程序中使用-ncurses" aria-label="Permalink to “在程序中使用 ncurses”">​</a></h3><p>要在屏幕上直接尋址，你首先需要初始化 <code>ncurses</code> 庫。大部分程序會通過以下三行來做到這一點：</p><ul><li><code>initscr()</code>：初始化窗口對象和 ncurses 代碼，返回代表整個屏幕的窗口對象</li><li><code>cbreak()</code>：禁用緩衝並使鍵入的輸入立即可用</li><li><code>noecho()</code>：關閉回顯，因此用户輸入不會顯示在屏幕上</li></ul><p>這些函數定義在 <code>curses.h</code> 頭文件中，你需要在你的程序中通過以下方式將其包含進來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;curses.h&gt;</span></span></code></pre></div><p>初始化終端後，你可以自由使用任何 ncurses 函數，我們將在示例程序中探討其中的一些函數。</p><p>當你使用完 ncurses 並想返回到常規終端模式下時，使用 <code>endwin()</code> 重置一切。此命令可以重置任何屏幕顏色，將光標移動到屏幕的左下角，並使光標可見。通常在退出程序之前執行此操作。</p><h3 id="在屏幕上尋址" tabindex="-1">在屏幕上尋址 <a class="header-anchor" href="#在屏幕上尋址" aria-label="Permalink to “在屏幕上尋址”">​</a></h3><p>關於 ncurses 首先需要知道的是屏幕的座標分為行和列，左上角的是 <code>0,0</code> 點。ncurses 定義了兩個全局變量來幫助你識別屏幕：<code>LINES</code> 是屏幕的行數，<code>COLS</code> 是屏幕的列數。屏幕右下角的位置是 <code>LINES-1,COLS-1</code>。</p><p>例如，如果你想要移動光標到第 10 行和第 30 列，你可以使用 <code>move()</code> 函數，移動到此座標：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>move(10, 30);</span></span></code></pre></div><p>之後顯示的任何文本都將從屏幕的該位置開始。要顯示單個字符，請對單個字符使用 <code>addch(c)</code> 函數。要顯示字符串，將對字符串使用 <code>addstr(s)</code> 函數。對於類似於 <code>printf</code> 的格式化輸出，請使用帶有常用選項的 <code>printw(fmt, ...)</code>。</p><p>移動到屏幕指定位置和顯示文本是一件很常見的事情，ncurses 提供了同時執行這兩項操作的快捷方式。<code>mvaddch(row, col, c)</code> 函數將在屏幕第 <code>row</code> 行，第 <code>col</code> 列的位置顯示一個字符。而 <code>mvaddstr(row, col, s)</code> 函數將在屏幕第 <code>row</code> 行，第 <code>col</code> 列的位置顯示一個字符串。舉個更直接的例子，在程序中使用 <code>mvaddstr(10, 30, &quot;Welcome to ncurses&quot;);</code> 函數將從屏幕的第 <code>10</code> 行和第 <code>30</code> 列開始顯示文本 <code>Welcome to ncurses</code>。使用 <code>mvaddch(0, 0, &#39;+&#39;)</code> 函數將在屏幕的左上角第 <code>0</code> 行和第 <code>0</code> 列處顯示一個加號（<code>+</code>）。</p><p>在終端屏幕上繪製文本會對某些系統產生性能影響，尤其是在較舊的硬件終端上。因此 ncurses 允許你“堆疊”一堆文本以顯示在屏幕上，然後使用 <code>refresh()</code> 函數使所有這些更改對用户可見。</p><p>讓我們來看一個將以上所有內容整合在一起的簡單示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;curses.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int</span></span>
<span class="line"><span>main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  initscr();</span></span>
<span class="line"><span>  cbreak();</span></span>
<span class="line"><span>  noecho();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  mvaddch(0, 0, &#39;+&#39;);</span></span>
<span class="line"><span>  mvaddch(LINES - 1, 0, &#39;-&#39;);</span></span>
<span class="line"><span>  mvaddstr(10, 30, &quot;press any key to quit&quot;);</span></span>
<span class="line"><span>  refresh();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  getch();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  endwin();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>程序的開始初始化了一個終端窗口，然後在屏幕的左上角打印了一個加號，在左下角打印了一個減號，在第 <code>10</code> 行和第 <code>30</code> 列打印了 <code>press any key to quit</code> 文本。程序通過使用 <code>getch()</code> 函數接收了鍵盤輸入的單個字符，接着，使用 <code>endwin()</code> 函數在程序完全退出前重置了終端。</p><p><code>getch()</code> 是一個很有用的函數，你可以使用它來做很多事情。我經常使用它在我退出程序前用來暫停。與大多數 ncurses 函數一樣，還有一個名為 <code>mvgetch(row, col)</code> 的 <code>getch()</code> 版本，用於在等待字符輸入之前移動到屏幕位置的第 <code>row</code> 行，第 <code>col</code> 列。</p><h3 id="使用-ncurses-編譯" tabindex="-1">使用 ncurses 編譯 <a class="header-anchor" href="#使用-ncurses-編譯" aria-label="Permalink to “使用 ncurses 編譯”">​</a></h3><p>如果你嘗試以通常的方式編譯該示例程序，例如 <code>gcc pause.c</code>，你可能會從鏈接器中獲得大量錯誤列表。那是因為 GNU C 編譯器不會自動鏈接 <code>ncurses</code> 庫。相反，你需要使用 <code>-l ncurses</code> 命令列選項加載它以進行鏈接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -o pause pause.c -lncurses</span></span></code></pre></div><p>運行新程序將打印一條簡單的 <code>press any key to quit</code>消息，該消息差不多位於屏幕中央：</p><p><img src="https://opensource.com/sites/default/files/press-key_0.png" alt="centered message in a program window"></p><p><em>圖 1：程序中居中的 “press any key to quit” 消息。</em></p><h3 id="使用-ncurses-構建更好的程序" tabindex="-1">使用 ncurses 構建更好的程序 <a class="header-anchor" href="#使用-ncurses-構建更好的程序" aria-label="Permalink to “使用 ncurses 構建更好的程序”">​</a></h3><p>探索 <code>ncurses</code> 庫函數以瞭解在屏幕上顯示文本的其它方法。你可以在 <code>ncurses</code> 的手冊頁中找到所有 <code>ncurses</code> 函數的列表。這給出了 ncurses 的一般概述，並提供了不同 <code>ncurses</code> 函數的類似表格的列表，並參考了包含完整詳細信息的手冊頁。例如，在 <code>curs_printw(3X)</code> 手冊頁中描述了 <code>printw</code>，可以通過以下方式查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man 3x curs_printw</span></span></code></pre></div><p>更簡單點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man curs_printw</span></span></code></pre></div><p>使用 ncurses，你可以創建更多有趣的程序。通過在屏幕上的特定位置打印文本，你可以創建在終端中運行的遊戲和高級實用程序。</p><hr>`,37)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/21/8/ncurses-linux"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/8/ncurses-linux",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[e("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(n,{href:"https://github.com/perfiffer"},{default:i(()=>[...s[4]||(s[4]=[e("perfiffer",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=c(l,[["render",u]]);export{y as __pageData,C as default};
